    {
      "name": "Finset.nnnorm_prod_le",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : Type u_5} [inst : NormedCommRing α] [NormOneClass α] (s : Finset ι) (f : ι → α),\n  ‖∏ i ∈ s, f i‖₊ ≤ ∏ i ∈ s, ‖f i‖₊"
    },
    {
      "name": "MvPolynomial.coeff_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (p q : MvPolynomial σ R) (n : σ →₀ ℕ),\n  MvPolynomial.coeff n (p * q) = ∑ x ∈ Finset.antidiagonal n, MvPolynomial.coeff x.1 p * MvPolynomial.coeff x.2 q"
    },
    {
      "name": "Int.instNormMulClass",
      "module_name": "Mathlib.Analysis.Normed.Ring.Lemmas",
      "kind": "instance",
      "type": "NormMulClass ℤ"
    },
    {
      "name": "norm_prod",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SeminormedCommRing α] [NormMulClass α] [NormOneClass α] (s : Finset β)\n  (f : β → α), ‖∏ b ∈ s, f b‖ = ∏ b ∈ s, ‖f b‖"
    },
    {
      "name": "NormedDivisionRing.toNormMulClass",
      "module_name": "Mathlib.Analysis.Normed.Field.Basic",
      "kind": "instance",
      "type": "∀ {α : Type u_2} [inst : NormedDivisionRing α], NormMulClass α"
    },
    {
      "name": "Finset.nnnorm_prod_le'",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_4} {α : Type u_5} [inst : NormedCommRing α] (s : Finset ι),\n  s.Nonempty → ∀ (f : ι → α), ‖∏ i ∈ s, f i‖₊ ≤ ∏ i ∈ s, ‖f i‖₊"
    },
    {
      "name": "MvPolynomial.mul_def",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {p q : MvPolynomial σ R},\n  p * q = Finsupp.sum p fun m a => Finsupp.sum q fun n b => (MvPolynomial.monomial (m + n)) (a * b)"
    },
    {
      "name": "Multipliable.norm_tprod",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Field",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_2} [inst : SeminormedCommRing E] [NormMulClass E] [NormOneClass E] {f : α → E},\n  Multipliable f → ‖∏' (i : α), f i‖ = ∏' (i : α), ‖f i‖"
    }
  ]
}
